def test_concurrent_seal_and_derive_share_the_version_sequence(self):
    procs, each = 3, 4
    raw_specs = [
        (f"seal-{p}-{i}", f"seal-{p}-{i}".encode("utf-8"))
        for p in range(procs)
        for i in range(each)
    ]
    derive_specs = [
        (
            f"pw-{p}-{i}".encode("utf-8"),
            f"salt-{p}-{i}".encode("utf-8"),
            100,
            16,
        )
        for p in range(procs)
        for i in range(each)
    ]
    workers = [
        multiprocessing.Process(
            target=_seal_worker,
            args=(
                str(self.root),
                "shared",
                [payload for _, payload in raw_specs],
            ),
        )
    ]
    workers += [
        multiprocessing.Process(
            target=_derive_worker,
            args=(str(self.root), "shared", derive_specs),
        )
        for _ in range(procs)
    ] if False else [
        multiprocessing.Process(
            target=_derive_worker,
            args=(str(self.root), "shared", [s for s in derive_specs]),
        )
    ]
    workers += [
        multiprocessing.Process(target=_reload_worker, args=(str(self.root), 20))
    ]
    self._run_workers(workers)

    vault = self.open_vault()
    total = procs * each + len(derive_specs)
    self.assertEqual(vault.versions("shared"), list(range(1, total + 1)))
    self.assertEqual(vault.active("shared"), total)

    expected_raw = {payload for _, payload in raw_specs}
    expected_derived = {
        (
            salt,
            100,
            16,
            hashlib.pbkdf2_hmac("sha256", password, salt, 100, 16),
        )
        for password, salt, _, _ in derive_specs
    }
    seen_raw: set[bytes] = set()
    seen_derived: set[tuple] = set()
    for version in vault.versions("shared"):
        material = vault.load("shared", version)
        record = vault.derivation("shared", version)
        if record:
            self.assertEqual(len(material), record["length"])
            seen_derived.add(
                (record["salt"], record["iterations"],
                 record["length"], material)
            )
        else:
            seen_raw.add(material)
    self.assertEqual(seen_raw, expected_raw)
    self.assertEqual(seen_derived, expected_derived)

    # A fresh handle revalidates every derivation record on disk.
    reloaded = self.open_vault()
    reloaded.reload()
    self.assertEqual(reloaded.versions("shared"), list(range(1, total + 1)))

